patch:
diff --git a/recreate-19957.js b/recreate-19957.js
new file mode 100644
index 0000000..06d4fbb
--- /dev/null
+++ b/recreate-19957.js
@@ -0,0 +1,42 @@
+"use strict";
+
+// Reproduction for "no-loss-of-precision incorrectly flags 9.000e+3".
+// Every literal below is exactly representable as a double, so the rule must
+// not report it. Exits non-zero while the bug is present, zero once fixed.
+
+const { Linter } = require("./lib/api");
+
+const linter = new Linter();
+const config = [{ rules: { "no-loss-of-precision": "error" } }];
+
+// literal -> the value it denotes
+const cases = [
+	// the reported input
+	["9.000e+3", 9000],
+	// the maintainer's variants that were also reported as errors
+	["9.000e3", 9000],
+	["9.0000e4", 90000],
+	// controls from the report that are already accepted (no trigger)
+	["9.000e4", 90000],
+	["9.0000e5", 900000],
+	["9e3", 9000],
+	["9000", 9000],
+];
+
+let failed = false;
+
+for (const [literal, expected] of cases) {
+	if (Number(literal) !== expected) {
+		throw new Error(`bad test data: ${literal} !== ${expected}`);
+	}
+	const messages = linter.verify(`const test = ${literal};`, config);
+
+	if (messages.length) {
+		failed = true;
+		console.log(`FAIL ${literal.padEnd(9)} (= ${expected}) -> ${messages.map(m => `${m.ruleId}: ${m.message}`).join("; ")}`);
+	} else {
+		console.log(`ok   ${literal.padEnd(9)} (= ${expected}) -> no report`);
+	}
+}
+
+process.exitCode = failed ? 1 : 0;
